  ('orthodox','Eastern Orthodox','The Greek and Slavic communion of autocephalous churches.',2,'sapphire'),
  ('undivided','Undivided Church','The shared trunk of the first millennium — and later attempts to rejoin it.',3,'gold'),
  ('catholic','Roman Catholic','The Latin West gathered around the See of Rome.',4,'ruby'),
  ('protestant','Lutheran & Reformed','The magisterial Reformation of Luther, Zwingli and Calvin.',5,'emerald'),
