insert into public.timeline_groups(id,title,date_label,start_year,end_year,auto_expand_zoom) values
  ('paul-life-and-journeys','Paul''s Life & Journeys','c. AD 34–67',34,67,1.35)
on conflict (id) do update set title=excluded.title,date_label=excluded.date_label,start_year=excluded.start_year,end_year=excluded.end_year,auto_expand_zoom=excluded.auto_expand_zoom;

insert into public.timeline_events(id,year,date_label,title,tradition_id,kind,icon,summary,detail,key_figures,links,group_id) values
  ('pentecost',33,'c. AD 33','Pentecost','undivided','event','{"type":"lucide","name":"Flame"}'::jsonb,'Fifty days after the resurrection, the Spirit falls on the disciples gathered in Jerusalem and the church begins to preach publicly.','Acts 2 describes tongues of fire, a rush of wind and Peter preaching to a crowd drawn from across the Mediterranean world. Roughly three thousand are baptised in a single day.

Every branch on this chart traces its descent through this moment. Whatever else divides them, Pentecost is the common root: a Jewish messianic movement in Jerusalem that within a generation had congregations from Rome to Mesopotamia.',array['Peter','The Eleven','Mary and the women of Galilee']::text[],'[{"label":"Pentecost — Wikipedia","url":"https://en.wikipedia.org/wiki/Pentecost"},{"label":"Acts 2 (Bible Gateway)","url":"https://www.biblegateway.com/passage/?search=Acts%202"}]'::jsonb,null),
  ('conversion-of-paul',35,'c. AD 34–36','Conversion of Paul','undivided','event','{"type":"lucide","name":"Sun"}'::jsonb,'Saul of Tarsus encounters the risen Jesus while travelling to Damascus and becomes a Christian.','According to Acts 9, Saul was travelling to arrest followers of Jesus when a heavenly light stopped him. After Ananias baptised him, the former persecutor became the most influential missionary to the Gentile world.',array['Paul of Tarsus','Ananias of Damascus']::text[],'[{"label":"Conversion of Paul — Wikipedia","url":"https://en.wikipedia.org/wiki/Conversion_of_Paul_the_Apostle"}]'::jsonb,'paul-life-and-journeys'),
  ('paul-first-journey',46,'c. AD 46–48','Paul''s First Missionary Journey','undivided','event','{"type":"lucide","name":"Compass"}'::jsonb,'Paul and Barnabas carry the gospel from Antioch through Cyprus and southern Asia Minor.','Sent by the church at Antioch, Paul and Barnabas preached in synagogues and founded mixed Jewish-Gentile communities across Cyprus and the cities of southern Asia Minor.',array['Paul of Tarsus','Barnabas','John Mark']::text[],'[{"label":"Paul''s first journey — Wikipedia","url":"https://en.wikipedia.org/wiki/First_missionary_journey"}]'::jsonb,'paul-life-and-journeys'),
  ('paul-second-journey',51,'c. AD 50–52','Paul''s Second Missionary Journey','undivided','event','{"type":"lucide","name":"Ship"}'::jsonb,'Paul crosses into Macedonia and plants churches at Philippi, Thessalonica, Berea and Corinth.','Travelling with Silas and later Timothy and Luke, Paul carried the mission into Europe. He addressed the Areopagus in Athens and remained in Corinth for roughly eighteen months.',array['Paul of Tarsus','Silas','Timothy','Luke']::text[],'[{"label":"Paul the Apostle — Wikipedia","url":"https://en.wikipedia.org/wiki/Paul_the_Apostle"}]'::jsonb,'paul-life-and-journeys'),
  ('paul-third-journey',54,'c. AD 53–57','Paul''s Third Missionary Journey','undivided','event','{"type":"lucide","name":"Globe"}'::jsonb,'Paul strengthens earlier churches and conducts an extended ministry in Ephesus.','Ephesus became the centre of Paul’s longest sustained ministry. From there the message spread through Roman Asia while Paul corresponded with churches and gathered aid for Jerusalem.',array['Paul of Tarsus','Timothy','Titus']::text[],'[{"label":"Paul the Apostle — Wikipedia","url":"https://en.wikipedia.org/wiki/Paul_the_Apostle"}]'::jsonb,'paul-life-and-journeys'),
  ('paul-arrested',57,'c. AD 57','Paul Arrested in Jerusalem','undivided','event','{"type":"lucide","name":"Swords"}'::jsonb,'Paul is seized after returning to Jerusalem and spends two years imprisoned at Caesarea.','A disturbance in the temple led Roman soldiers to take Paul into custody. He defended himself before Jewish and Roman authorities and appealed his case to Caesar as a Roman citizen.',array['Paul of Tarsus','Felix','Festus']::text[],'[{"label":"Paul the Apostle — Wikipedia","url":"https://en.wikipedia.org/wiki/Paul_the_Apostle"}]'::jsonb,'paul-life-and-journeys'),
  ('paul-voyage-rome',60,'c. AD 60–61','Paul''s Voyage to Rome','undivided','event','{"type":"lucide","name":"Anchor"}'::jsonb,'Paul travels to Rome as a prisoner, surviving a shipwreck on Malta.','Acts closes with a vivid account of storm, shipwreck and winter on Malta. Paul eventually reached Rome and lived under house arrest while preaching openly.',array['Paul of Tarsus','Luke','Julius the centurion']::text[],'[{"label":"Paul the Apostle — Wikipedia","url":"https://en.wikipedia.org/wiki/Paul_the_Apostle"}]'::jsonb,'paul-life-and-journeys'),
  ('martyrdom-of-paul',67,'c. AD 64–67','Martyrdom of Paul','undivided','event','{"type":"lucide","name":"Swords"}'::jsonb,'Early Christian tradition holds that Paul is executed at Rome during Nero’s persecution.','The New Testament does not narrate Paul’s death, but early testimony associates his martyrdom with Rome. Later tradition says his Roman citizenship led to execution by beheading.',array['Paul of Tarsus','Nero']::text[],'[{"label":"Paul the Apostle — Wikipedia","url":"https://en.wikipedia.org/wiki/Paul_the_Apostle"}]'::jsonb,'paul-life-and-journeys'),
  ('jerusalem-council',50,'c. AD 50','Council of Jerusalem','undivided','council','{"type":"lucide","name":"Users"}'::jsonb,'The apostles rule that Gentile believers need not be circumcised, opening the church beyond its Jewish matrix.','Acts 15 records the first great controversy: must Gentile converts keep the Law of Moses? Paul and Barnabas argue no; James proposes a minimal set of conditions; the assembly agrees.

The decision is the reason there is a world church rather than a Jewish sect. It also establishes the pattern that would define the next thousand years — disputed questions settled by a gathered council rather than by a single voice.',array['James the Just','Paul of Tarsus','Barnabas','Peter']::text[],'[{"label":"Council of Jerusalem — Wikipedia","url":"https://en.wikipedia.org/wiki/Council_of_Jerusalem"}]'::jsonb,null),
  ('edict-milan',313,'313','Edict of Milan','undivided','event','{"type":"lucide","name":"ScrollText"}'::jsonb,'Constantine and Licinius grant Christians legal toleration, ending three centuries of intermittent persecution.','Property is restored, worship is legalised and bishops begin to receive imperial patronage. Within a lifetime Christianity moves from an illegal association to the favoured religion of the Roman state.

The consequences run in both directions. The church gains basilicas, archives and public influence; it also gains an emperor with opinions about doctrine, which shapes every council that follows.',array['Constantine I','Licinius']::text[],'[{"label":"Edict of Milan — Wikipedia","url":"https://en.wikipedia.org/wiki/Edict_of_Milan"}]'::jsonb,null),
  ('nicaea',325,'325','First Council of Nicaea','undivided','council','{"type":"lucide","name":"Landmark"}'::jsonb,'The first ecumenical council rejects Arianism and confesses the Son as "of one substance" with the Father.','Around three hundred bishops meet at Constantine''s summons to answer the Alexandrian presbyter Arius, who taught that the Son was the first and highest creature. The council answers with the term homoousios — of one being with the Father.

Nicaea also fixed the dating of Easter and issued canons on church order. Its creed, expanded at Constantinople in 381, remains the one confession recited by Catholics, Orthodox, Anglicans and most Protestants alike.',array['Athanasius of Alexandria','Arius','Constantine I','Ossius of Córdoba']::text[],'[{"label":"First Council of Nicaea — Wikipedia","url":"https://en.wikipedia.org/wiki/First_Council_of_Nicaea"},{"label":"Nicene Creed — Wikipedia","url":"https://en.wikipedia.org/wiki/Nicene_Creed"}]'::jsonb,null),
  ('constantinople-i',381,'381','First Council of Constantinople','undivided','council','{"type":"lucide","name":"Feather"}'::jsonb,'Nicaea is reaffirmed and the creed is expanded to confess the deity of the Holy Spirit.','Half a century of Arian ascendancy is finally reversed under Theodosius I. The Cappadocian theologians — Basil, Gregory of Nazianzus, Gregory of Nyssa — supply the vocabulary of one essence in three persons.

The council also raised the bishop of Constantinople to a rank second only to Rome, a status claim that would irritate the Latin West for centuries and feed the estrangement that ends in 1054.',array['Gregory of Nazianzus','Basil the Great','Theodosius I']::text[],'[{"label":"First Council of Constantinople — Wikipedia","url":"https://en.wikipedia.org/wiki/First_Council_of_Constantinople"}]'::jsonb,null),
  ('ephesus',431,'431','Council of Ephesus','undivided','schism','{"type":"lucide","name":"Scale"}'::jsonb,'Nestorius is condemned and Mary is confessed as Theotokos — the first lasting division in the church.','The dispute was about how divinity and humanity are united in Christ, and whether Mary can properly be called Mother of God. Cyril of Alexandria pressed the case against Nestorius, patriarch of Constantinople, whose formula seemed to divide Christ into two subjects.

Ephesus produced the first branch on this chart that never rejoined. The East Syriac church beyond the Roman frontier refused the condemnation of its teachers and continued as a separate communion.',array['Cyril of Alexandria','Nestorius','Theodosius II']::text[],'[{"label":"Council of Ephesus — Wikipedia","url":"https://en.wikipedia.org/wiki/Council_of_Ephesus"}]'::jsonb,null),
  ('church-of-east',431,'431 onward','Church of the East','east-syriac','event','{"type":"lucide","name":"Compass"}'::jsonb,'The Syriac-speaking church of the Persian Empire declines the Ephesine settlement and develops its own hierarchy under the Catholicos of Seleucia-Ctesiphon.','Outside Roman jurisdiction, the East Syriac church answered to the Sasanian shahs rather than the emperor, and its theology preserved the Antiochene emphasis on the full humanity of Christ.

Far from marginal, it became the most geographically extensive church of the Middle Ages, with metropolitans in Merv, Herat, India and China. Modern heirs include the Assyrian Church of the East and the Chaldean Catholic Church.',array['Babai the Great','Narsai of Nisibis']::text[],'[{"label":"Church of the East — Wikipedia","url":"https://en.wikipedia.org/wiki/Church_of_the_East"}]'::jsonb,null),
  ('chalcedon',451,'451','Council of Chalcedon','undivided','schism','{"type":"lucide","name":"Gavel"}'::jsonb,'Christ is defined as one person in two natures — a formula much of Egypt, Syria and Armenia could not accept.','The Chalcedonian Definition steered between Nestorius and Eutyches: one person, made known in two natures, without confusion, change, division or separation. Pope Leo''s Tome was read as the standard of orthodoxy.

The wording split the Eastern church. Those who held to Cyril''s "one incarnate nature" — miaphysites — rejected the council, and imperial pressure hardened the divide into permanent separation. Modern dialogue suggests much of the quarrel was over vocabulary rather than substance.',array['Pope Leo I','Marcian','Dioscorus of Alexandria']::text[],'[{"label":"Council of Chalcedon — Wikipedia","url":"https://en.wikipedia.org/wiki/Council_of_Chalcedon"},{"label":"Chalcedonian Definition — Wikipedia","url":"https://en.wikipedia.org/wiki/Chalcedonian_Definition"}]'::jsonb,null),
  ('oriental-communion',451,'451 onward','Oriental Orthodox Communion','oriental','event','{"type":"lucide","name":"Sun"}'::jsonb,'The Coptic, Syriac, Armenian, Ethiopian and later Indian churches continue outside the Chalcedonian settlement.','These churches accept the first three ecumenical councils and confess one united nature of the incarnate Word. Their liturgies — Coptic, West Syriac, Armenian, Ge''ez — are among the oldest continuously used rites in Christianity.

Severus of Antioch gave the position its mature theological form. Under Muslim rule from the seventh century, these communities became durable minority churches, several of which survive as majority-shaping institutions in Egypt, Armenia and Ethiopia.',array['Severus of Antioch','Jacob Baradaeus','Dioscorus of Alexandria']::text[],'[{"label":"Oriental Orthodoxy — Wikipedia","url":"https://en.wikipedia.org/wiki/Oriental_Orthodoxy"}]'::jsonb,null),
  ('dvin',506,'506','Council of Dvin','oriental','council','{"type":"lucide","name":"Mountain"}'::jsonb,'The Armenian church formally rejects Chalcedon, setting its own confessional course.','Armenia had been absent from Chalcedon, occupied with war and persecution. At Dvin its bishops endorsed the Henotikon and repudiated the council, aligning the Armenian Apostolic Church with the miaphysite churches of Egypt and Syria.

A second synod at Dvin in 555 confirmed the decision. Armenian Christianity — with its own alphabet, liturgy and monastic culture — became one of the strongest markers of national identity in the Christian world.',array['Catholicos Babken I']::text[],'[{"label":"Armenian Apostolic Church — Wikipedia","url":"https://en.wikipedia.org/wiki/Armenian_Apostolic_Church"}]'::jsonb,null),
  ('gregory-great',590,'590','Gregory the Great elected','undivided','event','{"type":"lucide","name":"Crown"}'::jsonb,'A Roman monk becomes pope, reorganises the Western church and sends missionaries to the English.','With imperial power collapsing in Italy, Gregory fed the city, negotiated with the Lombards and administered vast church estates — in effect governing Rome. His Pastoral Rule became the standard handbook for medieval bishops.

He also despatched Augustine to Kent in 597, planting the see of Canterbury. The papacy that Luther and Henry VIII would later confront takes recognisable shape here.',array['Gregory I','Augustine of Canterbury']::text[],'[{"label":"Pope Gregory I — Wikipedia","url":"https://en.wikipedia.org/wiki/Pope_Gregory_I"}]'::jsonb,null),
  ('east-syriac-china',635,'635','East Syriac mission to China','east-syriac','event','{"type":"lucide","name":"Ship"}'::jsonb,'The monk Alopen reaches the Tang capital of Chang''an, and Christianity is preached in Chinese for the first time.','The Xi''an Stele, erected in 781, records the mission in Chinese and Syriac: imperial audiences, translated scriptures and monasteries under Tang patronage.

At its height the Church of the East stretched from Egypt to the Pacific along the Silk Road — the largest Christian communion on earth by area, though little remembered in the West.',array['Alopen','Emperor Taizong of Tang']::text[],'[{"label":"Xi''an Stele — Wikipedia","url":"https://en.wikipedia.org/wiki/Xi%27an_Stele"}]'::jsonb,null),
  ('nicaea-ii',787,'787','Second Council of Nicaea','undivided','council','{"type":"lucide","name":"Key"}'::jsonb,'The veneration of icons is restored, ending the first iconoclast controversy.','For half a century emperors had ordered the destruction of religious images. The council distinguished veneration offered to an image from the worship due to God alone, and defended icons as a consequence of the incarnation.

This is the last council recognised as ecumenical by both East and West. After it, the two halves of Christendom largely stop legislating together — the road to 1054 runs through that silence.',array['Empress Irene','John of Damascus','Patriarch Tarasios']::text[],'[{"label":"Second Council of Nicaea — Wikipedia","url":"https://en.wikipedia.org/wiki/Second_Council_of_Nicaea"}]'::jsonb,null),
  ('great-schism',1054,'16 July 1054','The Great Schism','undivided','schism','{"type":"lucide","name":"Split"}'::jsonb,'Papal legates and the patriarch of Constantinople excommunicate one another, formalising the rupture between East and West.','Cardinal Humbert laid a bull of excommunication on the altar of Hagia Sophia; Patriarch Michael Cerularius answered in kind. The immediate quarrels were over the filioque clause, unleavened bread, clerical marriage and papal jurisdiction.

The deeper causes were centuries of political and linguistic drift between a Greek East and a Latin West. Contemporaries did not think the split permanent — but repeated attempts at reunion failed, and the mutual anathemas stood until 1965.',array['Michael I Cerularius','Cardinal Humbert','Pope Leo IX']::text[],'[{"label":"East–West Schism — Wikipedia","url":"https://en.wikipedia.org/wiki/East%E2%80%93West_Schism"}]'::jsonb,null),
  ('eastern-orthodoxy',1054,'1054 onward','Eastern Orthodox Church','orthodox','event','{"type":"lucide","name":"Church"}'::jsonb,'The Greek East continues as a communion of self-governing churches holding the seven councils, with Constantinople first in honour.','Orthodoxy is organised as a family of autocephalous churches rather than a single jurisdiction. The ecumenical patriarch is first among equals, not a pope; doctrine is held to be settled by the seven councils and guarded by the whole body of the faithful.

Its worship — the Divine Liturgy of John Chrysostom, icons, the hesychast tradition of prayer — has changed remarkably little in a thousand years.',array['Gregory Palamas','Photios I','Symeon the New Theologian']::text[],'[{"label":"Eastern Orthodox Church — Wikipedia","url":"https://en.wikipedia.org/wiki/Eastern_Orthodox_Church"}]'::jsonb,null),
  ('roman-catholicism',1054,'1054 onward','Roman Catholic Church','catholic','event','{"type":"lucide","name":"Landmark"}'::jsonb,'The Latin West consolidates around the papacy, canon law and the universities.','The reforming popes of the eleventh century asserted the independence of the church from lay rulers and the primacy of Rome over all bishops. Out of that programme came canon law, the friars, scholastic theology and the medieval university.

By 1300 the Western church was the most sophisticated administrative institution in Europe — and the accumulated grievances against that institution supplied the tinder for 1517.',array['Gregory VII','Thomas Aquinas','Innocent III','Francis of Assisi']::text[],'[{"label":"Catholic Church — Wikipedia","url":"https://en.wikipedia.org/wiki/Catholic_Church"}]'::jsonb,null),
  ('fourth-crusade',1204,'1204','Sack of Constantinople','orthodox','event','{"type":"lucide","name":"Swords"}'::jsonb,'Crusaders divert to Constantinople, sack the city and install a Latin patriarch — hardening the schism into lasting bitterness.','For three days the army of the Fourth Crusade looted the greatest Christian city in the world, stripping Hagia Sophia and shipping relics west. A Latin empire was set up over Greek territory for nearly sixty years.

Whatever theological hopes remained for reunion did not survive this. Pope John Paul II apologised for the sack in 2001; Orthodox memory of it is still vivid.',array['Enrico Dandolo','Boniface of Montferrat','Pope Innocent III']::text[],'[{"label":"Fourth Crusade — Wikipedia","url":"https://en.wikipedia.org/wiki/Fourth_Crusade"}]'::jsonb,null),
  ('western-schism',1378,'1378–1417','The Western Schism','catholic','schism','{"type":"lucide","name":"Split"}'::jsonb,'Rival popes in Rome and Avignon — and briefly a third in Pisa — divide Latin Christendom for a generation.','Competing lines of popes excommunicated each other and each other''s followers while kingdoms picked sides. Only the Council of Constance (1414–18) resolved it, by deposing claimants and electing Martin V.

The episode did lasting damage to papal prestige and gave weight to conciliarism — the claim that a general council outranks a pope. It also produced Hus and Wycliffe, whose reforming ideas anticipated the next century.',array['Urban VI','Clement VII','Jan Hus','Martin V']::text[],'[{"label":"Western Schism — Wikipedia","url":"https://en.wikipedia.org/wiki/Western_Schism"}]'::jsonb,null),
  ('florence',1439,'1439','Council of Florence','orthodox','reunion','{"type":"lucide","name":"Handshake"}'::jsonb,'A reunion of East and West is signed under military pressure — and repudiated almost at once in the East.','With the Ottomans at the gates, Byzantine emperor John VIII sought Western help and accepted a union that conceded the filioque and papal primacy. Mark of Ephesus refused to sign.

The clergy and people of Constantinople rejected the terms; the promised crusade never materialised. Florence became the standard illustration in Orthodox memory that unity imposed from above does not hold.',array['John VIII Palaiologos','Bessarion','Mark of Ephesus','Pope Eugene IV']::text[],'[{"label":"Council of Florence — Wikipedia","url":"https://en.wikipedia.org/wiki/Council_of_Florence"}]'::jsonb,null),
  ('fall-of-constantinople',1453,'29 May 1453','Fall of Constantinople','orthodox','event','{"type":"lucide","name":"Anchor"}'::jsonb,'The Ottoman conquest ends the Byzantine Empire; the patriarchate continues under Muslim rule as head of the Orthodox millet.','Hagia Sophia became a mosque and the emperor died in the breach. The patriarch, however, was confirmed by Mehmed II as civil as well as religious head of the Orthodox population.

Greek scholars fleeing west fed the Renaissance; the church itself entered four centuries of survival under Ottoman rule, while leadership of Orthodox Christendom shifted north toward Moscow.',array['Mehmed II','Constantine XI','Gennadius Scholarius']::text[],'[{"label":"Fall of Constantinople — Wikipedia","url":"https://en.wikipedia.org/wiki/Fall_of_Constantinople"}]'::jsonb,null),
  ('ninety-five-theses',1517,'31 Oct 1517','The Ninety-five Theses','protestant','schism','{"type":"lucide","name":"Hammer"}'::jsonb,'Martin Luther attacks the sale of indulgences, and the printing press turns an academic dispute into the Protestant Reformation.','Luther meant to debate the theology of penance. Printers had his theses across Germany within weeks. By 1521 he had been excommunicated and outlawed, and had answered at Worms that he could not recant.

The programme that followed — justification by faith alone, the authority of Scripture over tradition, the priesthood of all believers, worship and Bibles in the vernacular — reorganised the religion of half of Europe within a single lifetime.',array['Martin Luther','Philip Melanchthon','Frederick the Wise','Pope Leo X']::text[],'[{"label":"Ninety-five Theses — Wikipedia","url":"https://en.wikipedia.org/wiki/Ninety-five_Theses"},{"label":"Reformation — Wikipedia","url":"https://en.wikipedia.org/wiki/Reformation"}]'::jsonb,null),
  ('zurich-baptisms',1525,'21 Jan 1525','First adult baptisms in Zürich','radical','schism','{"type":"lucide","name":"Droplet"}'::jsonb,'A small group re-baptises one another in defiance of the city council, beginning the Radical Reformation.','Conrad Grebel and his circle concluded that Zwingli had stopped half-way: if Scripture alone rules, infant baptism and a state-run church must both go. Their answer was a believers'' church of the voluntarily baptised.

Anabaptists were hunted by Catholics and Protestants alike. From them descend the Mennonites, Hutterites and Amish, and — through their influence on English Separatists — much of the Baptist tradition, along with the ideas of religious liberty and separation of church and state.',array['Conrad Grebel','Felix Manz','George Blaurock','Menno Simons']::text[],'[{"label":"Anabaptism — Wikipedia","url":"https://en.wikipedia.org/wiki/Anabaptism"}]'::jsonb,null),
  ('schleitheim',1527,'1527','Schleitheim Confession','radical','event','{"type":"lucide","name":"ScrollText"}'::jsonb,'Seven articles define the Anabaptist vision: believers'' baptism, church discipline, refusal of the sword and of oaths.','Drafted largely by Michael Sattler, the articles set out a separated church — pacifist, disciplined, deliberately distinct from civil society. Sattler was executed within months of signing.

Schleitheim remains the clearest early statement of free-church principle, and its influence reaches well beyond its own descendants into modern debates about church and state.',array['Michael Sattler']::text[],'[{"label":"Schleitheim Confession — Wikipedia","url":"https://en.wikipedia.org/wiki/Schleitheim_Confession"}]'::jsonb,null),
  ('augsburg-confession',1530,'25 June 1530','Augsburg Confession','protestant','event','{"type":"lucide","name":"BookOpen"}'::jsonb,'Melanchthon presents the Lutheran case to Charles V — the founding confession of a distinct Lutheran church.','Twenty-eight articles argue that the evangelical party teaches nothing contrary to the catholic faith, and list the abuses it has corrected. The emperor rejected it, and the Protestant princes formed a defensive league.

Augsburg gave Lutheranism a text to be measured by. The 1555 Peace of Augsburg then made confessional identity a matter of territorial law — cuius regio, eius religio — cementing the map of a divided Europe.',array['Philip Melanchthon','Charles V','John Frederick of Saxony']::text[],'[{"label":"Augsburg Confession — Wikipedia","url":"https://en.wikipedia.org/wiki/Augsburg_Confession"}]'::jsonb,null),
  ('act-of-supremacy',1534,'1534','Act of Supremacy — the Anglican split','anglican','schism','{"type":"lucide","name":"Crown"}'::jsonb,'Parliament declares Henry VIII supreme head of the Church of England, severing English jurisdiction from Rome.','The trigger was Henry''s desire to annul his marriage to Catherine of Aragon; the mechanism was statute law. The break was jurisdictional before it was doctrinal — the English church kept bishops, cathedrals and much of its liturgy while dissolving the monasteries and repudiating papal authority.

Doctrinal reform came under Edward VI, was reversed under Mary I, and was settled under Elizabeth I into a distinctive middle way: catholic order with reformed theology.',array['Henry VIII','Thomas Cranmer','Thomas Cromwell','Thomas More']::text[],'[{"label":"Act of Supremacy 1534 — Wikipedia","url":"https://en.wikipedia.org/wiki/Acts_of_Supremacy"},{"label":"English Reformation — Wikipedia","url":"https://en.wikipedia.org/wiki/English_Reformation"}]'::jsonb,null),
  ('institutes',1536,'1536','Calvin''s Institutes and the Reformed church','protestant','event','{"type":"lucide","name":"Printer"}'::jsonb,'John Calvin publishes the Institutes of the Christian Religion and begins to build a reformed city in Geneva.','The Institutes, revised until 1559, gave the Reformed wing a systematic theology: the sovereignty of God, election, covenant, and a church governed by pastors and elders rather than bishops.

Geneva became a school for exiles who carried Reformed Christianity to France, Scotland, the Netherlands, Hungary and eventually New England. Presbyterian, Congregational and Continental Reformed churches all descend from this stream.',array['John Calvin','Theodore Beza','John Knox','Huldrych Zwingli']::text[],'[{"label":"John Calvin — Wikipedia","url":"https://en.wikipedia.org/wiki/John_Calvin"},{"label":"Calvinism — Wikipedia","url":"https://en.wikipedia.org/wiki/Calvinism"}]'::jsonb,null),
  ('trent',1545,'1545–1563','Council of Trent','catholic','council','{"type":"lucide","name":"Gavel"}'::jsonb,'Rome answers the Reformation: doctrine is defined against Protestant positions and clerical abuses are reformed.','Over eighteen years and three sessions, Trent affirmed scripture and tradition together, seven sacraments, transubstantiation and justification as more than imputation — while abolishing the sale of indulgences and requiring seminaries and resident bishops.

The result was a confident, disciplined Catholicism that held the line in southern Europe and expanded across the Americas and Asia. Its settlement governed Catholic life until the 1960s.',array['Pope Paul III','Charles Borromeo','Ignatius of Loyola']::text[],'[{"label":"Council of Trent — Wikipedia","url":"https://en.wikipedia.org/wiki/Council_of_Trent"}]'::jsonb,null),
  ('book-of-common-prayer',1549,'1549','Book of Common Prayer','anglican','event','{"type":"lucide","name":"BookOpen"}'::jsonb,'Cranmer''s vernacular liturgy gives the English church a single prayer book — and English a body of enduring prose.','One use replaced the varied Latin rites of medieval England, in language ordinary people could follow. The 1552 revision moved further in a Reformed direction; the 1662 edition became the long-standing standard.

Anglican identity has rested more on common prayer than on a confession of faith. Wherever the tradition spread, the prayer book went with it.',array['Thomas Cranmer','Edward VI']::text[],'[{"label":"Book of Common Prayer — Wikipedia","url":"https://en.wikipedia.org/wiki/Book_of_Common_Prayer"}]'::jsonb,null),
  ('elizabethan-settlement',1559,'1559','Elizabethan Settlement','anglican','event','{"type":"lucide","name":"Scale"}'::jsonb,'Elizabeth I re-establishes a reformed but episcopal Church of England — the via media that defines Anglicanism.','The Acts of Supremacy and Uniformity, the Thirty-nine Articles and a revised prayer book together produced a church broad enough to hold Calvinist theology and traditional ceremony in the same building.

Some could not accept the compromise. Puritans pressed for further reform, and Separatists left altogether — a pressure that produced Congregationalists, English Baptists and, later, the Wesleyan revival within the establishment.',array['Elizabeth I','Matthew Parker','Richard Hooker']::text[],'[{"label":"Elizabethan Religious Settlement — Wikipedia","url":"https://en.wikipedia.org/wiki/Elizabethan_Religious_Settlement"}]'::jsonb,null),
  ('moscow-patriarchate',1589,'1589','Patriarchate of Moscow','orthodox','event','{"type":"lucide","name":"Church"}'::jsonb,'Moscow is raised to a patriarchate, and Russia becomes the political centre of gravity for Orthodoxy.','With Constantinople under Ottoman rule, the metropolitan of Moscow was elevated to patriarch with the consent of the Eastern patriarchs — an institutional expression of the idea of Moscow as a third Rome.

Abolished by Peter the Great in 1721 and restored in 1917, the patriarchate went on to endure the fiercest anti-religious campaign in Christian history under Soviet rule.',array['Patriarch Job','Boris Godunov','Jeremias II of Constantinople']::text[],'[{"label":"Russian Orthodox Church — Wikipedia","url":"https://en.wikipedia.org/wiki/Russian_Orthodox_Church"}]'::jsonb,null),
  ('baptists',1609,'1609','First Baptist congregation','radical','event','{"type":"lucide","name":"Droplet"}'::jsonb,'English Separatists in Amsterdam, influenced by Dutch Anabaptists, form the first identifiably Baptist church.','John Smyth baptised himself and his congregation on profession of faith; Thomas Helwys took part of the group back to London in 1612 and wrote one of the first English pleas for universal religious liberty.

Baptists combined Reformed theology with a free-church polity of self-governing congregations. Through the Particular and General Baptists, then the American frontier and the modern missionary movement, this became one of the largest Protestant families in the world.',array['John Smyth','Thomas Helwys','Roger Williams']::text[],'[{"label":"Baptists — Wikipedia","url":"https://en.wikipedia.org/wiki/Baptists"}]'::jsonb,null),
  ('westminster',1646,'1646','Westminster Confession','protestant','event','{"type":"lucide","name":"ScrollText"}'::jsonb,'The Westminster Assembly produces the confession and catechisms that define English-speaking Presbyterianism.','Convened by the Long Parliament during the civil wars, the assembly wrote a confession, two catechisms and a directory of worship on Reformed and presbyterian lines.

Though England reverted to episcopacy in 1660, the Westminster standards were adopted in Scotland and carried to Ireland, North America and beyond. They remain the doctrinal basis of Presbyterian churches worldwide.',array['The Westminster Divines','Samuel Rutherford']::text[],'[{"label":"Westminster Confession of Faith — Wikipedia","url":"https://en.wikipedia.org/wiki/Westminster_Confession_of_Faith"}]'::jsonb,null),
  ('pia-desideria',1675,'1675','Pietism — Pia Desideria','protestant','event','{"type":"lucide","name":"Heart"}'::jsonb,'Spener calls for heartfelt renewal inside Lutheran orthodoxy: small groups, lay Bible study, holiness of life.','Pia Desideria proposed devotional gatherings, practical preaching and better training for pastors. Halle became its university and Herrnhut, under Zinzendorf, its missionary engine.

Moravian Pietism proved contagious. It shaped Bach''s devotional world, launched Protestant foreign missions — and, through a Moravian meeting in London, reshaped John Wesley.',array['Philipp Jakob Spener','August Hermann Francke','Nikolaus von Zinzendorf']::text[],'[{"label":"Pietism — Wikipedia","url":"https://en.wikipedia.org/wiki/Pietism"}]'::jsonb,null),
  ('amish',1693,'1693','Amish division','radical','schism','{"type":"lucide","name":"Wheat"}'::jsonb,'Jakob Ammann''s stricter party separates from the Swiss Mennonites over discipline and shunning.','The dispute turned on the practice of social avoidance of excommunicated members and on foot washing. Ammann''s followers became the Amish; those who did not follow remained Mennonite.

Migration to Pennsylvania from the 1730s produced the plain communities that still practise a deliberately pre-industrial common life — one of the most visible survivals of the Radical Reformation.',array['Jakob Ammann']::text[],'[{"label":"Amish — Wikipedia","url":"https://en.wikipedia.org/wiki/Amish"}]'::jsonb,null),
  ('aldersgate',1738,'24 May 1738','Aldersgate — the Methodist revival','methodist','schism','{"type":"lucide","name":"Flame"}'::jsonb,'John Wesley''s heart is "strangely warmed" at a Moravian meeting, and a disciplined revival movement is born inside the Church of England.','Wesley never intended to leave the Church of England. But barred from many pulpits, he preached in fields, organised converts into classes and bands under lay leaders, and rode some quarter of a million miles doing it. Charles Wesley supplied the hymns; George Whitefield the transatlantic crowds.

Methodism''s distinctive notes were assurance, discipline and holiness — plus a conviction that grace is offered to all. Separation from the established church came gradually after Wesley''s death.',array['John Wesley','Charles Wesley','George Whitefield']::text[],'[{"label":"John Wesley — Wikipedia","url":"https://en.wikipedia.org/wiki/John_Wesley"},{"label":"Methodism — Wikipedia","url":"https://en.wikipedia.org/wiki/Methodism"}]'::jsonb,null),
  ('christmas-conference',1784,'1784','Christmas Conference, Baltimore','methodist','event','{"type":"lucide","name":"Tent"}'::jsonb,'American Methodists organise as an independent church, with circuit riders following the frontier west.','Wesley ordained ministers for America after the Revolution left its Methodists without sacraments. At Baltimore, Coke and Asbury were made superintendents of a new Methodist Episcopal Church.

Circuit riding and camp meetings fitted a scattered frontier population perfectly, and Methodism became the largest Protestant body in nineteenth-century America — before dividing bitterly over slavery.',array['Francis Asbury','Thomas Coke','Richard Allen']::text[],'[{"label":"Christmas Conference — Wikipedia","url":"https://en.wikipedia.org/wiki/Christmas_Conference"}]'::jsonb,null),
  ('lambeth',1867,'1867','First Lambeth Conference','anglican','event','{"type":"lucide","name":"Globe"}'::jsonb,'Bishops from across the empire meet at Lambeth, turning a national church into a worldwide communion.','Seventy-six bishops gathered at the invitation of the archbishop of Canterbury. The conference has no legislative power over independent provinces; it works by consultation and moral authority.

The Anglican Communion now spans some 165 countries, with its numerical centre in Africa. That breadth has also made it the setting for sharp modern disputes, since no single authority can settle them.',array['Charles Longley']::text[],'[{"label":"Lambeth Conference — Wikipedia","url":"https://en.wikipedia.org/wiki/Lambeth_Conference"}]'::jsonb,null),
  ('holiness-movement',1867,'1867','The Holiness movement','methodist','event','{"type":"lucide","name":"Sun"}'::jsonb,'Camp meetings revive Wesley''s teaching on entire sanctification, producing a family of new holiness churches.','The National Camp Meeting Association for the Promotion of Holiness, founded at Vineland, New Jersey, pressed for a second work of grace after conversion. Where established Methodism resisted, new bodies formed — the Church of God (Anderson), the Wesleyan Church, the Church of the Nazarene, the Salvation Army.

The movement also bequeathed the language of a "baptism of the Holy Spirit" that Pentecostalism would soon take in a new direction.',array['Phoebe Palmer','John Inskip','William and Catherine Booth']::text[],'[{"label":"Holiness movement — Wikipedia","url":"https://en.wikipedia.org/wiki/Holiness_movement"}]'::jsonb,null),
  ('vatican-i',1870,'1870','First Vatican Council','catholic','council','{"type":"lucide","name":"Crown"}'::jsonb,'Papal infallibility is defined, days before Italian troops end the Papal States.','The council taught that the pope, speaking ex cathedra on faith and morals, is preserved from error. It was interrupted when Rome fell to the Kingdom of Italy and never formally concluded.

A minority who rejected the definition left to form the Old Catholic churches. The pope, stripped of territory, gained an unprecedented concentration of spiritual authority.',array['Pope Pius IX','John Henry Newman','Ignaz von Döllinger']::text[],'[{"label":"First Vatican Council — Wikipedia","url":"https://en.wikipedia.org/wiki/First_Vatican_Council"}]'::jsonb,null),
  ('azusa-street',1906,'1906','Azusa Street Revival','pentecostal','schism','{"type":"lucide","name":"Wind"}'::jsonb,'A revival in a Los Angeles mission, led by William Seymour, launches global Pentecostalism.','For three years, services ran almost continuously in a converted building on Azusa Street, marked by speaking in tongues, healing and — strikingly for 1906 America — a racially integrated congregation under a Black pastor.

Visitors carried the movement worldwide within a decade. Pentecostal and charismatic Christianity is now counted in the hundreds of millions and is the fastest-growing stream in the church''s history, especially in Africa, Latin America and Asia.',array['William J. Seymour','Charles Parham','Lucy Farrow']::text[],'[{"label":"Azusa Street Revival — Wikipedia","url":"https://en.wikipedia.org/wiki/Azusa_Street_Revival"}]'::jsonb,null),
  ('assemblies-of-god',1914,'1914','Assemblies of God founded','pentecostal','event','{"type":"lucide","name":"Users"}'::jsonb,'Pentecostals begin to organise into denominations, giving the revival institutions, schools and missions.','Delegates met at Hot Springs, Arkansas, to form a cooperative fellowship for credentialing ministers and sending missionaries. Other bodies followed, including the largely Black Church of God in Christ, already organised in 1897 and reconstituted as Pentecostal in 1907.

Denominational structure made Pentecostalism durable and exportable — and eventually respectable enough to enter the evangelical mainstream.',array['E. N. Bell','Charles Harrison Mason','Aimee Semple McPherson']::text[],'[{"label":"Assemblies of God — Wikipedia","url":"https://en.wikipedia.org/wiki/Assemblies_of_God"}]'::jsonb,null),
  ('world-council',1948,'1948','World Council of Churches','undivided','reunion','{"type":"lucide","name":"Globe"}'::jsonb,'Orthodox, Anglican and Protestant churches form a fellowship in Amsterdam, and the branches begin to talk again.','Growing out of the missionary and Life-and-Work conferences of the early twentieth century, the WCC brought together 147 churches. It now includes some 350, representing more than half a billion Christians.

The Catholic Church is not a member but cooperates closely. Much of the twentieth century''s most significant church history is this: after a millennium of division, systematic conversation between branches that had excommunicated one another.',array['Willem Visser ''t Hooft','John R. Mott','Geoffrey Fisher']::text[],'[{"label":"World Council of Churches — Wikipedia","url":"https://en.wikipedia.org/wiki/World_Council_of_Churches"}]'::jsonb,null),
  ('charismatic-renewal',1960,'1960s','Charismatic renewal','pentecostal','event','{"type":"lucide","name":"Lightbulb"}'::jsonb,'Pentecostal experience spreads into Anglican, Catholic and mainline churches without founding new denominations.','It is usually dated to 1960, when Dennis Bennett, an Episcopal priest in Van Nuys, California, told his congregation he had spoken in tongues. Catholic renewal followed at Duquesne University in 1967 and was cautiously encouraged by Rome.

Unlike earlier revivals, this one largely crossed branches instead of splitting them — a rare case on this chart of a movement flowing sideways rather than forking.',array['Dennis Bennett','Kevin Ranaghan','Michael Harper']::text[],'[{"label":"Charismatic movement — Wikipedia","url":"https://en.wikipedia.org/wiki/Charismatic_movement"}]'::jsonb,null),
  ('vatican-ii',1962,'1962–1965','Second Vatican Council','catholic','council','{"type":"lucide","name":"BookOpen"}'::jsonb,'Rome reforms its liturgy, embraces religious liberty and calls other Christians separated brethren rather than heretics.','John XXIII called the council to open the windows of the church. Its documents permitted vernacular worship, redefined the church as the people of God, affirmed religious freedom, repudiated antisemitism and committed Catholicism to ecumenism.

No single event did more to change the tone of relations between the branches on this chart. It also produced internal division of its own, between those who thought it went too far and those who thought it stopped short.',array['John XXIII','Paul VI','Karl Rahner','Joseph Ratzinger']::text[],'[{"label":"Second Vatican Council — Wikipedia","url":"https://en.wikipedia.org/wiki/Second_Vatican_Council"}]'::jsonb,null),
  ('lifting-anathemas',1965,'7 Dec 1965','Catholic–Orthodox declaration','undivided','reunion','{"type":"lucide","name":"Handshake"}'::jsonb,'Paul VI and Athenagoras I jointly remove the excommunications of 1054 from the memory of the church.','A joint declaration read simultaneously in Rome and Istanbul expressed regret for the offensive words and gestures of 1054 and lifted the mutual anathemas. The two had already embraced in Jerusalem in 1964, the first meeting of pope and ecumenical patriarch in over five centuries.

Full communion has not been restored — papal primacy remains the substantive obstacle — but the formal state of mutual condemnation is over.',array['Paul VI','Athenagoras I']::text[],'[{"label":"Catholic–Orthodox Joint Declaration of 1965 — Wikipedia","url":"https://en.wikipedia.org/wiki/Catholic%E2%80%93Orthodox_Joint_Declaration_of_1965"}]'::jsonb,null),
  ('chambesy',1990,'1990','Chambésy agreement','oriental','reunion','{"type":"lucide","name":"Handshake"}'::jsonb,'Eastern and Oriental Orthodox theologians agree that their christologies are in substance the same, after fifteen centuries apart.','The joint commission concluded that both families confess the one Christ, fully God and fully human, and that the split of 451 rested largely on differing uses of the word "nature".

The statements recommended lifting the ancient anathemas. Formal unity has not yet followed, but the theological case for the oldest division in Christianity has been substantially withdrawn by both sides.',array['Joint Commission of the Orthodox Churches']::text[],'[{"label":"Oriental Orthodoxy — Wikipedia","url":"https://en.wikipedia.org/wiki/Oriental_Orthodoxy"}]'::jsonb,null),
  ('assyrian-declaration',1994,'11 Nov 1994','Common Christological Declaration','east-syriac','reunion','{"type":"lucide","name":"Handshake"}'::jsonb,'John Paul II and Mar Dinkha IV declare a common faith in Christ, closing the dispute begun at Ephesus in 431.','Signed in the Vatican, the declaration states that the historic quarrel arose from differing terminology rather than differing faith, and that both churches confess Christ as true God and true man.

It is the oldest breach in the church to receive such a settlement — 1,563 years after the council that caused it. Guidelines for shared sacraments between Assyrian and Chaldean faithful followed in 2001.',array['John Paul II','Mar Dinkha IV']::text[],'[{"label":"Common Christological Declaration — Wikipedia","url":"https://en.wikipedia.org/wiki/Common_Christological_Declaration_Between_the_Catholic_Church_and_the_Assyrian_Church_of_the_East"}]'::jsonb,null),
  ('joint-declaration-justification',1999,'31 Oct 1999','Joint Declaration on Justification','undivided','reunion','{"type":"lucide","name":"Handshake"}'::jsonb,'Catholics and Lutherans declare a consensus on the doctrine that divided them in 1517, and the condemnations no longer apply.','Signed in Augsburg on Reformation Day, the declaration states that we are justified by grace alone through faith in Christ''s saving work, and that the sixteenth-century condemnations do not apply to the teaching now set out by each side.

Methodists joined in 2006, Anglicans and the Reformed later. Real differences remain about authority, ministry and the sacraments — but the specific question that started the Reformation has been formally, jointly answered.',array['Edward Cassidy','Christian Krause']::text[],'[{"label":"Joint Declaration on the Doctrine of Justification — Wikipedia","url":"https://en.wikipedia.org/wiki/Joint_Declaration_on_the_Doctrine_of_Justification"}]'::jsonb,null),
  ('crete-council',2016,'2016','Holy and Great Council of Crete','orthodox','council','{"type":"lucide","name":"Users"}'::jsonb,'The first pan-Orthodox council in centuries meets in Crete — without four of the fourteen churches.','Decades in preparation, the council addressed mission, marriage, fasting, the diaspora and relations with other Christians. Antioch, Georgia, Bulgaria and, decisively, Moscow stayed away.

The absences illustrate the working difficulty of Orthodox conciliarity, and prefigured the 2018 rupture between Moscow and Constantinople over Ukraine — a reminder that this chart is still being drawn.',array['Bartholomew I']::text[],'[{"label":"Pan-Orthodox Council — Wikipedia","url":"https://en.wikipedia.org/wiki/Pan-Orthodox_Council"}]'::jsonb,null)
